from control.iosys import _parse_spec
from control.statesp import ss


def _systems():
    plant = ss(
        [[0.0]], [[1.0, 0.0]], [[1.0], [2.0]], [[0.0, 0.0], [0.0, 0.0]],
        name="plant", inputs=["cmd", "dist"], outputs=["pos", "vel"])
    gain = ss(
        [], [], [], [[1.0, -1.0], [2.0, 3.0]],
        name="gain", inputs=["left", "right"], outputs=["mix", "trim"])
    return [plant, gain]


class TestParseSpecGainDependencyVariabilityQA:
    def test_case_01(self):
        assert _parse_spec(_systems(), ("plant", "pos"), "output") == (0, [0], 1)

    def test_case_02(self):
        assert _parse_spec(_systems(), ("plant", "vel", 2.5), "output") == (0, [1], 2.5)

    def test_case_03(self):
        assert _parse_spec(_systems(), "-plant.pos", "output") == (0, [0], -1)

    def test_case_04(self):
        assert _parse_spec(_systems(), ("plant", "-vel"), "output") == (0, [1], -1)

    def test_case_05(self):
        assert _parse_spec(_systems(), ("gain", "mix", -3), "output") == (1, [0], -3)

    def test_case_06(self):
        assert _parse_spec(_systems(), "-gain.trim", "output") == (1, [1], -1)

    def test_case_07(self):
        assert _parse_spec(_systems(), ("gain", "-right"), "input") == (1, [1], -1)

    def test_case_08(self):
        assert _parse_spec(_systems(), ("plant", "cmd", 0.25), "input") == (0, [0], 0.25)

    def test_case_09(self):
        assert _parse_spec(_systems(), "gain.left", "input") == (1, [0], 1)

    def test_case_10(self):
        assert _parse_spec(_systems(), ("plant", "dist"), "input") == (0, [1], 1)
from control.config import defaults
from control.iosys import _process_dt_keyword


class TestProcessDtDependencyVariabilityQA:
    def test_case_01(self):
        assert _process_dt_keyword({}, {}, static=True) is None

    def test_case_02(self):
        assert _process_dt_keyword({"dt": 0.1}, {}, static=True) == 0.1

    def test_case_03(self):
        assert _process_dt_keyword({}, {"dt": 0.2}, static=True) == 0.2

    def test_case_04(self):
        assert _process_dt_keyword({"dt": True}, {"dt": 0.3}, static=False) is True

    def test_case_05(self):
        old = defaults["control.default_dt"]
        try:
            defaults["control.default_dt"] = 0.4
            assert _process_dt_keyword({}, {}, static=False) == 0.4
        finally:
            defaults["control.default_dt"] = old

    def test_case_06(self):
        assert _process_dt_keyword({"dt": None}, {"dt": 0.5}, static=False) is None

    def test_case_07(self):
        assert _process_dt_keyword({}, {"dt": True}, static=False) is True

    def test_case_08(self):
        old = defaults["control.default_dt"]
        try:
            defaults["control.default_dt"] = None
            assert _process_dt_keyword({}, {}, static=False) is None
        finally:
            defaults["control.default_dt"] = old

    def test_case_09(self):
        assert _process_dt_keyword({"dt": 0}, {}, static=True) == 0

    def test_case_10(self):
        assert _process_dt_keyword({}, {"dt": None}, static=True) is None

